-- LogForge Seed Dump from Local MySQL
SET FOREIGN_KEY_CHECKS=0;
CREATE DATABASE IF NOT EXISTS `logforge` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `logforge`;

DROP TABLE IF EXISTS `alembic_version`;
CREATE TABLE `alembic_version` (
  `version_num` varchar(32) NOT NULL,
  PRIMARY KEY (`version_num`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

LOCK TABLES `alembic_version` WRITE;
UNLOCK TABLES;

DROP TABLE IF EXISTS `events`;
CREATE TABLE `events` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `event_id` varchar(36) NOT NULL,
  `timestamp` datetime DEFAULT NULL,
  `detected_format` varchar(32) NOT NULL,
  `source_ip` varchar(64) DEFAULT NULL,
  `destination_ip` varchar(64) DEFAULT NULL,
  `source_port` int(11) DEFAULT NULL,
  `destination_port` int(11) DEFAULT NULL,
  `protocol` varchar(32) DEFAULT NULL,
  `action` varchar(64) DEFAULT NULL,
  `severity` varchar(32) DEFAULT NULL,
  `raw_event` text NOT NULL,
  `normalized_event` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`normalized_event`)),
  `additional_fields` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`additional_fields`)),
  `sha256_hash` varchar(64) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_events_event_id` (`event_id`),
  KEY `ix_events_timestamp` (`timestamp`),
  KEY `ix_events_detected_format` (`detected_format`),
  KEY `ix_events_source_ip` (`source_ip`),
  KEY `ix_events_destination_ip` (`destination_ip`),
  KEY `ix_events_action` (`action`),
  KEY `ix_events_severity` (`severity`),
  KEY `ix_events_created_at` (`created_at`),
  KEY `ix_events_timestamp_severity` (`timestamp`,`severity`)
) ENGINE=InnoDB AUTO_INCREMENT=60 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

LOCK TABLES `events` WRITE;
UNLOCK TABLES;

DROP TABLE IF EXISTS `event_anomalies`;
CREATE TABLE `event_anomalies` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `event_id` varchar(36) NOT NULL,
  `anomaly_score` float NOT NULL,
  `classification` varchar(32) NOT NULL,
  `explanation` text NOT NULL,
  `model_name` varchar(64) NOT NULL,
  `model_version` varchar(32) NOT NULL,
  `features_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`features_snapshot`)),
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_event_anomalies_event_id` (`event_id`),
  KEY `ix_event_anomalies_anomaly_score` (`anomaly_score`),
  KEY `ix_event_anomalies_classification` (`classification`),
  KEY `ix_anomalies_score_created` (`anomaly_score`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=60 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

LOCK TABLES `event_anomalies` WRITE;
UNLOCK TABLES;

DROP TABLE IF EXISTS `integrity_batches`;
CREATE TABLE `integrity_batches` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `batch_id` varchar(36) NOT NULL,
  `root_hash` varchar(64) NOT NULL,
  `event_count` int(11) NOT NULL DEFAULT 0,
  `status` varchar(32) NOT NULL DEFAULT 'PENDING',
  `blockchain_status` varchar(32) NOT NULL DEFAULT 'PENDING',
  `blockchain_tx_hash` varchar(66) DEFAULT NULL,
  `blockchain_network` varchar(64) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `anchored_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_integrity_batches_batch_id` (`batch_id`),
  KEY `ix_integrity_batches_root_hash` (`root_hash`),
  KEY `ix_integrity_batches_blockchain_status` (`blockchain_status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

LOCK TABLES `integrity_batches` WRITE;
UNLOCK TABLES;

DROP TABLE IF EXISTS `event_integrity`;
CREATE TABLE `event_integrity` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `event_id` varchar(36) NOT NULL,
  `sha256_hash` varchar(64) NOT NULL,
  `hash_algorithm` varchar(16) NOT NULL DEFAULT 'SHA-256',
  `previous_hash` varchar(64) DEFAULT NULL,
  `chain_hash` varchar(64) DEFAULT NULL,
  `batch_id` varchar(36) DEFAULT NULL,
  `verification_status` varchar(32) NOT NULL DEFAULT 'UNVERIFIED',
  `blockchain_status` varchar(32) NOT NULL DEFAULT 'PENDING',
  `blockchain_tx_hash` varchar(66) DEFAULT NULL,
  `blockchain_network` varchar(64) DEFAULT NULL,
  `blockchain_anchor` varchar(66) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `verified_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_event_integrity_event_id` (`event_id`),
  KEY `ix_event_integrity_sha256_hash` (`sha256_hash`),
  KEY `ix_event_integrity_created_at` (`created_at`),
  KEY `ix_event_integrity_verification_status` (`verification_status`),
  KEY `ix_event_integrity_blockchain_status` (`blockchain_status`),
  KEY `ix_event_integrity_batch_id` (`batch_id`),
  KEY `ix_event_integrity_verification_created` (`verification_status`,`created_at`),
  CONSTRAINT `event_integrity_ibfk_1` FOREIGN KEY (`event_id`) REFERENCES `events` (`event_id`) ON DELETE CASCADE,
  CONSTRAINT `event_integrity_ibfk_2` FOREIGN KEY (`batch_id`) REFERENCES `integrity_batches` (`batch_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

LOCK TABLES `event_integrity` WRITE;
UNLOCK TABLES;

SET FOREIGN_KEY_CHECKS=1;
